        "questionText": "Tip-Top Cleaning Supply carries a large number of different items in its inventory, giving the company a competitive advantage in its industry. Below is part of Tip-Top’s budget for the first quarter of next year.<div class='table-responsive'><table class='mcq-table'><tbody><tr><td>Sales</td><td>$855,000</td></tr><tr><td>Cost of goods sold</td><td>425,000</td></tr><tr><td>Rent and salary expenses</td><td>375,000</td></tr></tbody></table></div>Historically, all of the sales are on account and are made evenly over the quarter. 5% of all sales are determined to be uncollectible and written off. The balance of the receivables is collected in 50 days. This sales and collection experience is expected to continue in the first quarter. The projected balance sheet for the first day of the quarter includes the following account balances.<div class='table-responsive'><table class='mcq-table'><tbody><tr><td>Cash</td><td>$ 10,000</td></tr><tr><td>Accounts receivable (net)</td><td>450,000</td></tr><tr><td>Inventory</td><td>900,000</td></tr><tr><td>Accounts payable</td><td>800,000</td></tr></tbody></table></div>How much cash can Tip-Top anticipate collecting in the first quarter (based on a 360-day year)?",
