        "id": 96,
        "questionText": "Data regarding Johnsen Inc.’s forecasted dollar sales for the last seven months of the year and Johnsen’s projected collection patterns are as follows.<br><br>Forecasted sales<div class='table-responsive'><table class='mcq-table'><tbody><tr><td>June</td><td>$700,000</td></tr><tr><td>July</td><td>600,000</td></tr><tr><td>August</td><td>650,000</td></tr><tr><td>September</td><td>800,000</td></tr><tr><td>October</td><td>850,000</td></tr><tr><td>November</td><td>900,000</td></tr><tr><td>December</td><td>840,000</td></tr></tbody></table></div>Types of sales<div class='table-responsive'><table class='mcq-table'><tbody><tr><td>Cash sales</td><td>30%</td></tr><tr><td>Credit sales</td><td>70%</td></tr></tbody></table></div>Collection pattern on credit sales (5% determined to be uncollectible)<div class='table-responsive'><table class='mcq-table'><tbody><tr><td>During the month of sale</td><td>20%</td></tr><tr><td>During the first month following the sale</td><td>50%</td></tr><tr><td>During the second month following the sale</td><td>25%</td></tr></tbody></table></div>Johnsen’s budgeted cash receipts from sales and collections on account for September are",
