        "correct": "D",
        "explanation": "The actual wage rate per hour is $7.50 and the actual hours worked equals 38 as shown below.\n\nActual hours: (X – 40) x $7 = -$14\nX – 40 = -2\nX = 38 hours\nWage rate: (X - $7) x 38 = $19\nX - $7 = $ .50\nX = $7.50"
