        "id": 48,
        "questionText": "Kern Manufacturing has several divisions and evaluates performance using segment income. Since sales include transfers to other divisions, Kern has established a price for internal sales as cost plus 10%. Red Division has requested 10,000 units of Green Division’s product. Green Division is selling its product externally at a 60% markup over cost. The corporate policy will encourage the Green Division to",
