        "explanation": "If Zinten is produced, income would increase by $2,000 calculated as follows.\n\nChange in income: = Xylo – Zinten sales differential – Additional cost\n= [ 2,000 x ($15 - $12)] - $4,000\n= $6,000 - $4,000\n= $2,000"
