        "id": 51,
        "questionText": "A company produces disk brakes for mountain bikes. During the current reporting period, the company has normal spoilage of 700 units. At the beginning of the current reporting period, the company had 3,400 units in inventory and started and completed 5,600 units. 4,900 units were transferred out, and ending inventory had 3,100 units. In this reporting period, the abnormal spoilage for the company disk brakes production was",
