        "questionText": "Atmel Inc. manufactures and sells two products. Data with regard to these products are given below.<div class='table-responsive'><table class='mcq-table'><thead><tr><th></th><th>Product A Product B</th></tr></thead><tbody><tr><td>Units produced and sold</td><td>30,000 12,000</td></tr><tr><td>Machine hours required per unit</td><td>2              3</td></tr><tr><td>Receiving orders per product line</td><td>50 150</td></tr><tr><td>Production orders per product line</td><td>12 18</td></tr><tr><td>Production runs</td><td>8             12</td></tr><tr><td>Inspections</td><td>20 30</td></tr></tbody></table></div>Total budgeted machine hours are 100,000. The budgeted overhead costs are shown below.<div class='table-responsive'><table class='mcq-table'><tbody><tr><td>Receiving costs</td><td>$450,000</td></tr><tr><td>Engineering costs</td><td>300,000</td></tr><tr><td>Machine setup costs</td><td>25,000</td></tr><tr><td>Inspection costs</td><td>200,000</td></tr><tr><td>Total budgeted overhead</td><td>$975,000</td></tr></tbody></table></div>The cost driver for engineering costs is the number of production orders per product line. Using activity-based costing, the engineering cost per unit for Product B would be",
