        "questionText": "An equipment manufacturer uses an online order-entry system for its customers so that they can order electronic parts from anywhere in the world. Due to the cost and sensitive nature of several of the electronic parts, the manufacturer needs to maintain a secure order-entry system. The most effective technique for monitoring the security of access is",
