    "id": 5,
    "questionText": "A manufacturing company has two departments, Machining and Assembly, at its Shanghai plant. This year's budget for the plant contained the following information.<div class='table-responsive'><table class='mcq-table'><thead><tr><th>Item</th><th>Machining</th><th>Assembly</th></tr></thead><tbody><tr><td>Manufacturing overhead</td><td>$4,000,000</td><td>$2,000,000</td></tr><tr><td>Direct labor hours</td><td>100,000</td><td>200,000</td></tr><tr><td>Machine hours</td><td>40,000</td><td>40,000</td></tr></tbody></table></div>If the Shanghai plant uses departmental allocation based on machine hours for the Machining Department and direct labor hours for the Assembly Department, what would the rates be when allocating overhead to the individual products?",
    "options": {
      "A": "Machining: $40/hr.; Assembly: $10/hr.",
      "B": "Machining: $75/hr.; Assembly: $30/hr.",
      "C": "Machining: $100/hr.; Assembly: $10/hr.",
      "D": "Machining: $100/hr.; Assembly: $50/hr."
    },
    "correct": "C",
    "explanation": "For the Machining Department, overhead is allocated on machine hours: Predetermined rate = $4,000,000 / 40,000 machine hours = $100 per machine hour. For the Assembly Department, overhead is allocated on direct labor hours: Predetermined rate = $2,000,000 / 200,000 direct labor hours = $10 per direct labor hour."
