    "questionText": "A company uses a normal costing system and a predetermined overhead rate to allocate its overhead costs. The manufacturing process requires the use of machining equipment, which is a primary driver of overhead. The actual factory overhead amount is $450 for Department A, Job 120 as of the end of the year. Production costs are shown below.<br>Estimated annual overhead for all departments: $220,000<br>Expected annual machine hours for all departments: 20,000<br>Actual machine hours for Department A, Job 120: 32<br>Actual labor hours for Department A, Job 120: 21<br>The overhead cost for Department A, Job 120 is",
