    "questionText": "A company operates on a calendar year but maintains four continuous quarterly budgets for up-to-date budget information. After completing its five-year long-term plan, the company's management decided to make a capital investment in new equipment. The equipment is expected to have a useful life of nine years. Which one of the following is the most appropriate time period for the capital budget for the evaluation of the capital investment?",
