    "id": 64,
    "questionText": "Which one of the following statements best describes the concept of continuous improvement when developing standard costs?",
    "options": {
      "A": "Standards become more challenging as time passes.",
      "B": "Standards are developed with zero slack or downtime factored into the calculation.",
      "C": "Standards remain unattainable to encourage employees to strive harder.",
      "D": "Standards are established at an easily attainable level to increase employee morale."
    },
    "correct": "A",
    "explanation": "Continuous improvement (Kaizen) costing assumes that production processes and employee learning evolve continuously over time[cite: 28]. Therefore, standard costs are progressively adjusted and tightened over successive periods to reflect expected efficiencies, making standards progressively more challenging[cite: 28]."
