    "questionText": "An auditing firm is concluding its audit of a publicly traded company in the U.S. After obtaining sufficient audit evidence, an external auditor concludes that misstatements in the aggregate are material but not pervasive to the financial statements. What type of opinion should the external auditor issue on the company's financial statements?",
    "options": {
      "A": "Unmodified opinion.",
      "B": "Qualified opinion.",
      "C": "Adverse opinion.",
      "D": "Disclaimer of opinion."
    },
    "correct": "B",
    "explanation": "Under auditing standards, when misstatements are material but not pervasive (i.e., they are confined to specific accounts and do not overshadow the overall fair presentation of the financial statements as a whole), the auditor issues a Qualified opinion ('except for')[cite: 31]. An Adverse opinion is issued only when misstatements are both material and pervasive[cite: 31]."
